const commandMinimal = global.get("commandMinimal");
if (!commandMinimal || typeof commandMinimal.buildNetErlRelay1Command !== "function") {
    msg.statusCode = 500;
    msg.payload = {
        error: "command_minimal_unavailable",
        message: "command helper missing"
    };
    return [null, msg];
}

try {
    const runtime = global.get("smarthome_runtime");
    const result = commandMinimal.buildNetErlRelay1Command(runtime, msg.payload);
    if (!result.ok) {
        msg.statusCode = result.statusCode || 400;
        msg.payload = {
            error: result.error,
            message: result.message
        };
        return [null, msg];
    }

    const mqttMsg = {
        topic: result.command.topic,
        payload: result.command.payload,
        qos: 0,
        retain: false
    };
    const responseMsg = {
        req: msg.req,
        res: msg.res,
        statusCode: 202,
        payload: result.response
    };
    return [mqttMsg, responseMsg];
} catch (error) {
    node.error(error, msg);
    msg.statusCode = 500;
    msg.payload = {
        error: "command_minimal_internal",
        message: error.message
    };
    return [null, msg];
}

